cd /workspace && node -e "
const ExcelJS = require('exceljs');

async function createExcel() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Emails');

  // Headers
  sheet.columns = [
    { header: 'From', key: 'from', width: 25 },
    { header: 'To', key: 'to', width: 25 },
    { header: 'Subject', key: 'subject', width: 20 },
    { header: 'Body', key: 'body', width: 50 },
  ];

  // Bold headers
  sheet.getRow(1).font = { bold: true };

  // Email 1: received
  sheet.addRow({
    from: 'bob@example.com',
    to: 'alice@example.com',
    subject: 'Hello',
    body: 'Hi Alice, just checking in!',
  });

  // Email 2: sent
  sheet.addRow({
    from: 'alice@example.com',
    to: 'carol@example.com',
    subject: 'Report',
    body: 'Please find the attached quarterly report.',
  });

  await workbook.xlsx.writeFile('/workspace/alice_emails.xlsx');
  console.log('Created alice_emails.xlsx');
}

createExcel();
"
